static int next_state(state,ch)
int state;
char ch;
{
    if(state < 0)
        return(state);
    if(base[state] + ch < 0)
    {
        if(check[base[state]+ch] == state)
            return(next[base[state]+ch]);
        else
            return(next_state(default1[state], ch));
    }
    else
    {
        if (state == COMMENT_STATE && ch == '\n')
            return(INITIAL);
        return(next_state(default1[state], ch));
    }
}
